check_weak_value(val) {
    val.ir_type == "String"
    regex.match("(?i)\\b(DES|3DES|RC4|Blowfish|CAST|IDEA|MD2|MD4|MD5|SHA1|ECB|XOR|ROT13|SSLv2|SSLv3|TLS[-_]?1[.-]0|TLS[-_]?1[.-]1)\\b", val.value)
