    val.ir_type == "String"
    lower_val := lower(val.value)
    weak_algorithms[_] == lower_val
} else {
    val.ir_type == "String"
    lower_val := lower(val.value)
    weak_protocols[_] == lower_val
}

check_insecure_flag(name, val) {
    val.ir_type == "Boolean"
    val.value == true
    lower_name := lower(name)
    insecure_flags[_] == lower_name
}

check_key_length(val) {
    val.ir_type == "Integer"
    val.value < 2048
}

